                    order.dealId.toLowerCase().includes(q) ||
                    order.user.name.toLowerCase().includes(q) ||
                    order.user.email.toLowerCase().includes(q);
                const matchesStatus = this.statusFilter === 'all' || order.status === this.statusFilter;
                return matchesSearch && matchesStatus;
            });
        },
        get allSelected() {
            return this.filteredOrders.length > 0 &&
                this.filteredOrders.every(order => this.selectedRows.includes(order.id));
        },
        toggleSelectAll() {
            if (this.allSelected) {
                const filteredIds = new Set(this.filteredOrders.map(o => o.id));
                this.selectedRows = this.selectedRows.filter(id => !filteredIds.has(id));
            } else {
                const filteredIds = this.filteredOrders.map(o => o.id);
                this.selectedRows = Array.from(new Set([...this.selectedRows, ...filteredIds]));
            }
        },
        toggleRow(id) {
            if (this.selectedRows.includes(id)) {
                this.selectedRows = this.selectedRows.filter(rowId => rowId !== id);
